using EEMS.SharedKernel.Domain;namespace EEMS.Modules.Operations.Domain;public sealed class ReadinessChecklist:Entity<Guid>{private ReadinessChecklist(){}private ReadinessChecklist(Guid id,Guid tenantId,Guid electionId,Guid electionCenterId,short stateId,string name){if(tenantId==Guid.Empty||electionId==Guid.Empty||electionCenterId==Guid.Empty)throw new ArgumentException("Checklist references are required.");if(stateId<=0)throw new ArgumentOutOfRangeException(nameof(stateId));Id=id;TenantId=tenantId;ElectionId=electionId;ElectionCenterId=electionCenterId;StateId=stateId;Name=OperationRules.Text(name,180);CreatedAtUtc=DateTimeOffset.UtcNow;Version=1;}public Guid TenantId{get;private set;}public Guid ElectionId{get;private set;}public Guid ElectionCenterId{get;private set;}public short StateId{get;private set;}public string Name{get;private set;}=string.Empty;public DateTimeOffset CreatedAtUtc{get;private set;}public int Version{get;private set;}public static ReadinessChecklist Create(Guid tenantId,Guid electionId,Guid centerId,short stateId,string name)=>new(Guid.NewGuid(),tenantId,electionId,centerId,stateId,name);public void Recalculate(short stateId){if(stateId<=0)throw new ArgumentOutOfRangeException(nameof(stateId));StateId=stateId;Version++;}}
